func countBlank(r io.Reader) (int, error) {
	sc := bufio.NewScanner(r)
	n := 0
	for sc.Scan() {
		if sc.Text() == "" {
			n++
		}
	}
	return n, sc.Err()
}

func main() {
	n, err := countBlank(strings.NewReader("a\n\n \n\t\nb"))
	fmt.Printf("blank=%d err=%v\n", n, err)
}

func CountEmpty(filename string) (int, error) {
	f, err := os.Open(filename)
	if err != nil {
		return 0, err
	}
	defer f.Close()
	sc := bufio.NewScanner(f)
	n := 0
	for sc.Scan() {
		if strings.TrimSpace(sc.Text()) == "" {
			n++
		}
	}
	return n, sc.Err()
}

func TestCountEmpty(t *testing.T) {
	n, err := CountEmpty("testdata/log.txt")
	if err != nil || n != 2 {
		t.Fatalf("n=%d err=%v", n, err)
	}
}
